// --- Build one .po file per locale from the translation matrix ----------------

function po_escape( $s ) {
	return str_replace( array( '\\', '"' ), array( '\\\\', '\\"' ), $s );
}

$written = array();
foreach ( $order as $idx => $locale ) {
	$po  = "# Translation of the Global Body Mass Index Calculator plugin.\n";
	$po .= "# Language: {$locales[$locale]} ({$locale}).\n";
	$po .= "msgid \"\"\nmsgstr \"\"\n";
	$po .= "\"Project-Id-Version: Global Body Mass Index Calculator 1.3\\n\"\n";
	$po .= "\"Content-Type: text/plain; charset=UTF-8\\n\"\n";
	$po .= "\"Content-Transfer-Encoding: 8bit\\n\"\n";
	$po .= "\"Language: {$locale}\\n\"\n";
	$po .= "\"MIME-Version: 1.0\\n\"\n";
	$po .= "\"PO-Revision-Date: " . gmdate( 'Y-m-d H:iO' ) . "\\n\"\n";
	$po .= "\"Last-Translator: Machine-assisted initial translation (native review welcome)\\n\"\n";
	$po .= "\"Language-Team: {$locales[ $locale ]}\\n\"\n\n";

	$count = 0;
	foreach ( $T as $id => $translations ) {
		$tr = isset( $translations[ $idx ] ) ? $translations[ $idx ] : '';
		if ( '' === $tr ) {
			continue; // Leave untranslated strings to fall back to the source.
		}
		$po .= 'msgid "' . po_escape( $id ) . "\"\n";
		$po .= 'msgstr "' . po_escape( $tr ) . "\"\n\n";
		$count++;
	}

	$file = "{$langs_dir}/{$slug}-{$locale}.po";
	file_put_contents( $file, $po );
	$written[ $locale ] = $count;
}

echo "Wrote " . count( $written ) . " .po files:\n";
foreach ( $written as $loc => $n ) {
	echo "  {$loc}: {$n} translated strings\n";
}
